pub fn rmse(errors: []const f64) f64 {
    var sum: f64 = 0;
    for (errors) |value| sum += value * value;
    return @sqrt(sum / c.f(errors.len));
}
pub fn real(value: f64) []const u8 {
    return c.fmt("{d:.4}", .{if (@abs(value) < 0.00005) @as(f64, 0) else value});
}
pub fn optionalReal(value: ?f64) []const u8 {
    return if (value) |number| real(number) else "-";
}
fn subsetErrors(errors: []const f64, indices: []const usize) c.Vector {
    const out = c.vector(indices.len);
    for (indices, out) |index, *value| value.* = errors[index];
    return out;
